private const val CAMPSITES_COLLECTION = "campsites"
private const val USERS_COLLECTION = "users"

private enum class ImageFilterMode(val label: String) {
    ALL("All Images"),
    SORT_CAMPSITE("Sort: Campsite A-Z"),
    SORT_OWNER("Sort: Owner A-Z"),
}

private data class AdminImageItem(
    val campsiteId: String,
    val campsiteName: String,
    val ownerId: String,
    val ownerLabel: String,
    val imageUrl: String,
    val timeLabel: String,
)

private fun decodeBase64Image(raw: String): ImageBitmap? {
    val clean = raw.substringAfter("base64,", raw).trim()
    if (clean.length < 32 || clean.startsWith("http://") || clean.startsWith("https://")) {
        return null
    }
    return runCatching {
        val bytes = Base64.decode(clean, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
    }.getOrNull()
}

/**
 * Documentation generated by Gemini
 * Composable screen for administrator image asset browsing and removal.
 *
 * @param navController Navigation controller for routing back to admin dashboard.
 */
@Composable
fun AdminImagesScreen(navController: NavController) {
    val backgroundColor = Color(0xFFFEFAE0)
    val buttonColor = Color(0xFF283618)
    val cardColor = Color(0xFFFAF3DD)

    var ownerNames by remember { mutableStateOf(emptyMap<String, String>()) }
    var rawCampsites by remember { mutableStateOf<List<Campsite>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var errorMessage by remember { mutableStateOf<String?>(null) }
    var actionMessage by remember { mutableStateOf<String?>(null) }

    var searchQuery by remember { mutableStateOf("") }
    var filterMode by remember { mutableStateOf(ImageFilterMode.ALL) }
    var filterMenuExpanded by remember { mutableStateOf(false) }

    var pendingDeleteItem by remember { mutableStateOf<AdminImageItem?>(null) }
    var isDeleting by remember { mutableStateOf(false) }

    DisposableEffect(Unit) {
        val db = FirebaseFirestore.getInstance()
        val listener = db.collection(CAMPSITES_COLLECTION)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    errorMessage = error.message ?: "Failed to load images."
                    isLoading = false
                    return@addSnapshotListener
                }
                errorMessage = null
                val sites = snapshot?.documents?.mapNotNull { doc ->
                    runCatching {
                        doc.toObject(Campsite::class.java)?.copy(campsiteId = doc.id)
                    }.getOrNull()
                }.orEmpty()
                rawCampsites = sites
                isLoading = false

                val missingOwnerIds = sites.mapNotNull { it.ownerId.takeIf(String::isNotBlank) }
                    .distinct()
                    .filter { it !in ownerNames }

                missingOwnerIds.forEach { ownerId ->
                    db.collection(USERS_COLLECTION).document(ownerId).get()
                        .addOnSuccessListener { userDoc ->
                            val name = userDoc.getString("name")?.takeIf { it.isNotBlank() }
                                ?: userDoc.toObject(User::class.java)?.name?.takeIf { it.isNotBlank() }
                                ?: ownerId
                            ownerNames = ownerNames + (ownerId to name)
                        }
                }
            }
        onDispose { listener.remove() }
    }

    val images: List<AdminImageItem> = remember(rawCampsites, ownerNames) {
        rawCampsites
            .filter { !it.imageUrl.isNullOrBlank() }
            .map { site ->
                val url = site.imageUrl.orEmpty()
                val ownerLabel = site.ownerId.takeIf { it.isNotBlank() }
                    ?.let { id -> ownerNames[id] ?: id }
                    ?: "Unknown Owner"
                AdminImageItem(
                    campsiteId = site.campsiteId,
                    campsiteName = site.name.ifBlank { "Unnamed Campsite" },
                    ownerId = site.ownerId,
                    ownerLabel = ownerLabel as String,
                    imageUrl = url,
                    timeLabel = "Uploaded (Firestore)",
                )
            }
    }

    val visibleImages: List<AdminImageItem> = remember(images, searchQuery, filterMode) {
        val q = searchQuery.trim().lowercase()
        val filtered = if (q.isEmpty()) {
            images
        } else {
            images.filter { item ->
                item.campsiteName.lowercase().contains(q) ||
                        item.ownerLabel.lowercase().contains(q) ||
                        item.ownerId.lowercase().contains(q) ||
                        item.imageUrl.lowercase().contains(q)
            }
        }
        when (filterMode) {
            ImageFilterMode.ALL -> filtered
            ImageFilterMode.SORT_CAMPSITE -> filtered.sortedBy { it.campsiteName.lowercase() }
            ImageFilterMode.SORT_OWNER -> filtered.sortedBy { it.ownerLabel.lowercase() }
        }
    }

    fun confirmDeleteImage(item: AdminImageItem) {
        if (isDeleting) return
        isDeleting = true
        errorMessage = null
        actionMessage = null
        FirebaseFirestore.getInstance()
            .collection(CAMPSITES_COLLECTION)
            .document(item.campsiteId)
            .update("imageUrl", FieldValue.delete())
            .addOnSuccessListener {
                isDeleting = false
                pendingDeleteItem = null
                actionMessage = "Removed image from ${item.campsiteName}."
            }
            .addOnFailureListener { err ->
                isDeleting = false
                errorMessage = err.message ?: "Failed to remove image."
            }
    }

    pendingDeleteItem?.let { target ->
        AlertDialog(
            onDismissRequest = { if (!isDeleting) pendingDeleteItem = null },
            title = { Text("Confirm Deletion") },
            text = {
                Text("Are you sure you want to delete this image for \"${target.campsiteName}\"?")
            },
            confirmButton = {
                Button(
                    onClick = { confirmDeleteImage(target) },
                    enabled = !isDeleting,
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFB3261E)),
                    modifier = Modifier.testTag("confirmDeleteImageButton"),
                ) {
                    Text(if (isDeleting) "Deleting..." else "Yes", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(
                    onClick = { pendingDeleteItem = null },
                    enabled = !isDeleting,
                    modifier = Modifier.testTag("cancelDeleteImageButton"),
                ) {
                    Text("No")
                }
            },
        )
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(backgroundColor)
            .statusBarsPadding()
            .padding(16.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RoundedCornerShape(8.dp),
                colors = ButtonDefaults.buttonColors(containerColor = buttonColor),
                modifier = Modifier.testTag("backButton"),
            ) {
                Text("< Back")
            }

            Text(
                text = "Images",
                fontSize = 28.sp,
                fontWeight = FontWeight.Bold,
                modifier = Modifier.testTag("imagesHeader"),
            )

            Spacer(modifier = Modifier.width(72.dp))
        }

        Spacer(modifier = Modifier.height(12.dp))

        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            OutlinedTextField(
                value = searchQuery,
                onValueChange = { searchQuery = it },
                placeholder = { Text("Search...") },
                singleLine = true,
                modifier = Modifier
                    .weight(1f)
                    .testTag("imageSearchField"),
            )
            Spacer(modifier = Modifier.width(8.dp))
            Box {
                Button(
                    onClick = { filterMenuExpanded = true },
                    shape = RoundedCornerShape(8.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = buttonColor),
                    modifier = Modifier.testTag("imageFilterButton"),
                ) {
                    Text("Filter")
                }
                DropdownMenu(
                    expanded = filterMenuExpanded,
                    onDismissRequest = { filterMenuExpanded = false },
                ) {
                    ImageFilterMode.entries.forEach { mode ->
                        DropdownMenuItem(
                            text = { Text(mode.label) },
                            onClick = {
                                filterMode = mode
                                filterMenuExpanded = false
                            },
                        )
                    }
                }
            }
        }

        errorMessage?.let {
            Spacer(modifier = Modifier.height(8.dp))
            Text(text = it, color = MaterialTheme.colorScheme.error, fontSize = 14.sp)
        }
        actionMessage?.let {
            Spacer(modifier = Modifier.height(8.dp))
            Text(text = it, color = buttonColor, fontSize = 14.sp)
        }

        Spacer(modifier = Modifier.height(12.dp))

        when {
            isLoading -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator(color = buttonColor)
                }
            }
            visibleImages.isEmpty() -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text(
                        text = if (searchQuery.isBlank()) {
                            "No uploaded images found."
                        } else {
                            "No images match your search."
                        },
                        fontSize = 16.sp,
                        modifier = Modifier.testTag("emptyImagesMessage"),
                    )
                }
            }
            else -> {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .testTag("adminImagesList"),
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                ) {
                    items(visibleImages, key = { it.campsiteId }) { item ->
                        val decodedBitmap = remember(item.imageUrl) { decodeBase64Image(item.imageUrl) }

                        Card(
                            colors = CardDefaults.cardColors(containerColor = cardColor),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .border(1.dp, buttonColor, RoundedCornerShape(8.dp))
                                .testTag("imageCard_${item.campsiteId}"),
                        ) {
                            Column(modifier = Modifier.padding(12.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                ) {
                                    Text(
                                        text = "Campsite: ${item.campsiteName}",
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis,
                                        modifier = Modifier.weight(1f),
                                    )
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text(
                                        text = "Owner: ${item.ownerLabel}",
                                        fontSize = 13.sp,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis,
                                    )
                                }
                                Text(
                                    text = item.timeLabel,
                                    fontSize = 12.sp,
                                    color = Color.DarkGray,
                                )

                                Spacer(modifier = Modifier.height(8.dp))

                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(160.dp)
                                        .background(Color.White, RoundedCornerShape(6.dp))
                                        .border(1.dp, Color.Gray, RoundedCornerShape(6.dp)),
                                    contentAlignment = Alignment.Center,
                                ) {
                                    if (decodedBitmap != null) {
                                        Image(
                                            bitmap = decodedBitmap,
                                            contentDescription = "Image for ${item.campsiteName}",
                                            contentScale = ContentScale.Crop,
                                            modifier = Modifier.fillMaxSize(),
                                        )
                                    } else {
                                        Column(
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            modifier = Modifier.padding(12.dp),
                                        ) {
                                            Text(
                                                text = "Image Reference",
                                                fontWeight = FontWeight.SemiBold,
                                                fontSize = 14.sp,
                                            )
                                            Spacer(modifier = Modifier.height(4.dp))
                                            Text(
                                                text = item.imageUrl,
                                                fontSize = 12.sp,
                                                maxLines = 2,
                                                overflow = TextOverflow.Ellipsis,
                                            )
                                        }
                                    }
                                }

                                Spacer(modifier = Modifier.height(10.dp))

                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.End,
                                ) {
                                    Button(
                                        onClick = { pendingDeleteItem = item },
                                        shape = RectangleShape,
                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFB3261E)),
                                        modifier = Modifier
                                            .size(width = 100.dp, height = 38.dp)
                                            .testTag("deleteImageButton_${item.campsiteId}"),
                                    ) {
                                        Text("Delete", color = Color.White, fontSize = 14.sp)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

